59	export const matchPredefinedErrorFromResponse = (response: Response, originalError?: CausableError) => {
60	  const errorDetails = NetworkRequestError.getNetworkRequestErrorDetailsFromResponse(response);
61	  switch (response.status) {
62	    case 400:
63	      return new BadRequestError(errorDetails, originalError);
64	    case 401:
65	      return new UnauthorizedError(errorDetails, originalError);
66	    case 403:
67	      return new PermissionError(errorDetails, originalError);
68	    case 404:
69	      return new NotFoundError(errorDetails, originalError);
70	    case 429:
71	      return new RateLimitedError(errorDetails, originalError);
72	    case 500:
73	      return new InternalServerError(errorDetails, originalError);
74	    case 503:
75	      return new ServiceUnavailableError(errorDetails, originalError);
76	    default:
77	      return new GenericNetworkRequestError(errorDetails, originalError);
78	  }
