import { useMutation } from '@mlflow/mlflow/src/common/utils/reactQueryHooks';
import { fetchOrFail } from '../../common/utils/FetchUtils';

export interface TryItError {
  message: string;
  responseBody?: string;
}

interface UseTryItOptions {
  tryItRequestUrl: string;
}

interface UseTryItResult {
  data: string | undefined;
  error: TryItError | undefined;
  isLoading: boolean;
  sendRequest: (body: string) => void;
  reset: () => void;
}

/**
 * Pretty-print a raw response body as JSON when possible, falling back to the raw text
 * when the payload is not valid JSON.
 */
const prettyPrintJson = (text: string): string => {
  try {
    return JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    return text;
  }
};

const toTryItError = async (err: unknown): Promise<TryItError> => {
  if (err instanceof NetworkRequestError && err.response) {
    let responseBody: string | undefined;
    try {
      responseBody = prettyPrintJson(await err.response.text());
    } catch {
      responseBody = undefined;
    }
    return { message: err.message, responseBody };
  }
  if (err instanceof Error) {
    return { message: err.message };
  }
  return { message: String(err) };
};

/**
 * Manages sending a POST request to the given URL and tracking data, error, and loading state.
 * The request body is provided as a raw string; if it is not valid JSON, the request is not
 * sent and an "Invalid JSON in request body" error is surfaced.
 */
export const useTryIt = ({ tryItRequestUrl }: UseTryItOptions): UseTryItResult => {
  const mutation = useMutation<string, TryItError, string>({
    mutationFn: async (body: string) => {
      let parsedBody: unknown;
      try {
        parsedBody = JSON.parse(body);
      } catch {
        throw { message: 'Invalid JSON in request body' } as TryItError;
      }

      try {
        const response = await fetchOrFail(tryItRequestUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(parsedBody),
        });
        return prettyPrintJson(await response.text());
      } catch (err) {
        throw await toTryItError(err);
      }
    },
  });

  return {
    data: mutation.data,
    error: mutation.error ?? undefined,
    isLoading: mutation.isLoading,
    sendRequest: (body: string) => mutation.mutate(body),
    reset: () => mutation.reset(),
  };
};
