/**
 * Error thrown by the try-it request flow. Carries an optional `responseBody` containing the
 * server's response text (pretty-printed) when the failure originated from an HTTP response.
 */
class TryItRequestError extends Error {
  responseBody?: string;

  constructor(message: string, responseBody?: string) {
    super(message);
    this.name = 'TryItRequestError';
    this.responseBody = responseBody;
  }
}

interface UseTryItOptions {
  tryItRequestUrl: string;
}

interface UseTryItResult {
  data: string | undefined;
  error: TryItError | undefined;
  isLoading: boolean;
  sendRequest: (body: string) => void;
  reset: () => void;
}

/**
 * Pretty-print a raw response body as JSON when possible, falling back to the raw text
 * when the payload is not valid JSON.
 */
const prettyPrintJson = (text: string): string => {
  try {
    return JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    return text;
  }
};

const toTryItError = async (err: unknown): Promise<TryItRequestError> => {
  if (err instanceof NetworkRequestError && err.response) {
    let responseBody: string | undefined;
    try {
      responseBody = prettyPrintJson(await err.response.text());
    } catch {
      responseBody = undefined;
    }
    return new TryItRequestError(err.message, responseBody);
  }
  if (err instanceof Error) {
    return new TryItRequestError(err.message);
  }
  return new TryItRequestError(String(err));
};

